mapper.select:
select o.*,q.id as queue_id,q.order_type,q.status,q.msg,q.create_time as queue_create_time,q.use_time
FROM t_erp_goods_order_queue q
left join erp_goods_order o on q.erp_goods_order_id = o.id


        AND o.order_sn like concat('%',#{orderSn},'%')


        AND o.created_by = #{createdBy}


        AND q.status = #{status}


        AND q.order_type = #{orderType}



        AND o.created_at >= #{startCreateTime}


        AND o.created_at <= #{endCreateTime}


        AND q.use_time >= #{startUseTime}


        AND q.use_time <= #{endUseTime}


        AND o.shop_type = #{shopType}


        AND o.shop_erp_name LIKE CONCAT('%',#{shopErpName},'%')


ORDER BY o.created_at desc
LIMIT #{pageNum}, #{pageSize}

SELECT COUNT(*)
FROM t_erp_goods_order_queue q
left join erp_goods_order o on q.erp_goods_order_id = o.id


        AND o.order_sn like concat('%',#{orderSn},'%')


        AND o.created_by = #{createdBy}


        AND q.status = #{status}


        AND q.order_type = #{orderType}


        AND o.created_at >= #{startCreateTime}


        AND o.created_at <= #{endCreateTime}


        AND q.use_time >= #{startUseTime}


        AND q.use_time <= #{endUseTime}


        AND o.shop_type = #{shopType}


        AND o.shop_erp_name LIKE CONCAT('%',#{shopErpName},'%')

SELECT

FROM t_erp_goods_order_queue


        AND id = #{id}


        AND erp_goods_order_id = #{erpGoodsOrderId}


        AND status = #{status}


        AND create_time = #{createTime}


        AND use_time = #{useTime}


        AND order_type = #{orderType}


ORDER BY id DESC

